// Custom deleter for a C-style file handle
#include <cstdio>
#include <memory>

auto file_closer = [](FILE* fp) {
    if (fp) {
        fclose(fp);
        // In a real app, you'd log this.
    }
};

// unique_ptr managing the FILE* with a custom deleter.
// The deleter's type is part of the unique_ptr's type.
std::unique_ptr<FILE, decltype(file_closer)> p_file(
    fopen("data.txt", "w"),
    file_closer
);

// Factory function returning a unique_ptr
class Resource {};
std::unique_ptr<Resource> make_resource() {
    return std::make_unique<Resource>();
}

// Easy conversion from unique_ptr to shared_ptr
auto u_ptr = make_resource();
// u_ptr now owns the Resource

std::shared_ptr<Resource> s_ptr = std::move(u_ptr);
// Ownership has been moved to s_ptr.
// u_ptr is now null.
